head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
    var options = {
        id: "common_message135206914",
        type: "wframePopup",
        width: "1300px",
        height: "600px",
        top: "120px",
        left: "220px",
        popupName: "testPopup2",
        modal: true,
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        dataObject: {
            "type": "json",
            "data": {
                "data": {
                    "msgType": "alert",
                    "msgStr": "조건을 입력하세요",
                    "etcStr": ""
                },
                "callbackFn": "mf_pop1134557335_wframe_scwin.closeCallbackFnc",
                "callbackFnObj": "",
                "objPre": "mf_pop1134557335_wframe_",
                "popupID": "mf_pop1134557335_wframe_common_message135206914"
            },
            "name": "param"
        }
    };
    $p.openPopup("gridView_in_popup_WEFF-791_(WSQ-4136)_sub.xml", options);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('common_message135206914_wframe_wq_uuid_7_scrollX_right').scrollLeft = 1000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('common_message135206914_wframe_wq_uuid_7_scrollX_right').scrollLeft = 2000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('common_message135206914_wframe_wq_uuid_7_scrollX_right').scrollLeft = 3000");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('common_message135206914_wframe_wq_uuid_7_head_table').style.width != '0px'", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
